7	const DEFAULT_ROUTER_SCHEME = 'hybrid://lynxview_page';
8	const PROTOCOL_REGEX = /^[a-z][a-z0-9+.-]*:\/\//i;
9	const ALLOWED_SCHEME_PARAMS = new Set<NavigateParamKey>([
10	    'bundle',
11	    'title',
12	    'fallback_url',
13	    'title_color',
